      "audioUrl": "media/sprakvagen-d-s59-kulturella-skillnader.mp3",
      "readingSlug": "paste-2026-09-22-kulturella-skillnader",
      "timingsApproximate": true,
      "note": "课本配套朗读（教材第 59–61 页 QR 码音频）。语速偏快，字幕时间轴为按字数估算，点句跳转可能有 1–2 秒误差。",
