      "source": "SVT Nyheter på lätt svenska",
      "cefr": "A2–B1",
      "duration": 272,
      "svtPlayUrl": "https://www.svtplay.se/video/8PBB39w/nyheter-pa-latt-svenska",
      "sourceUrl": "",
      "sourceLinkLabel": "",
      "audioUrl": "",
