      "hlsUrl": "https://svt-vod-7r.akamaized.net/d0/world/20260626/0eb64b47-7dc6-43a0-bc5d-9c1b91fc6f9a/hls-cmaf-full.m3u8",
      "vttUrl": "https://svt-vod-7r.akamaized.net/d0/world/20260626/0eb64b47-7dc6-43a0-bc5d-9c1b91fc6f9a/text/text-auto.vtt",
      "cueCount": 43,
      "vocabCount": 15,
      "cues": [
        {
          "start": 9.24,
          "end": 12.8,
          "sv": "Välkomna till Nyheter på lätt svenska.",
          "zh": "欢迎收看简易瑞典语新闻。"
        },
        {
          "start": 12.96,
          "end": 17.56,
          "sv": "Vi börjar i Venezuela. Nära 600 människor är döda",
          "zh": "我们从委内瑞拉开始。近600人遇难"
        },
        {
          "start": 17.72,
          "end": 21.96,
          "sv": "efter de två kraftiga jordbävningarna som drabbat landet.",
          "zh": "这是两次强烈地震袭击该国所造成的。"
        },
        {
          "start": 22.12,
          "end": 25.6,
          "sv": "Runt 3 000 personer är skadade.",
          "zh": "约3000人受伤。"
        },
        {
          "start": 25.76,
          "end": 30.16,
          "sv": "Antalet döda kommer troligtvis att öka mycket",
          "zh": "死亡人数很可能还会大幅增加"
        },
        {
          "start": 30.32,
          "end": 34.44,
          "sv": "och många länder skickar nu hjälp till Venezuela.",
          "zh": "许多国家现在正向委内瑞拉提供援助。"
        },
        {
          "start": 34.44,
          "end": 39.36,
          "sv": "De två kraftigaste jordbävningarna skedde med 40 sekunders mellanrum",
          "zh": "两次最强烈的地震相隔40秒发生"
        },
        {
          "start": 39.52,
          "end": 46.28,
          "sv": "i delstaten La Guaira, 17 mil från Venezuelas huvudstad Caracas.",
          "zh": "发生在拉瓜伊拉州，距委内瑞拉首都加拉加斯约170公里。"
        },
        {
          "start": 46.44,
          "end": 50.32,
          "sv": "Det bor många människor i det drabbade området.",
          "zh": "受灾地区住着很多人。"
        },
        {
          "start": 50.48,
          "end": 55.64,
          "sv": "Fler än 250 byggnader med lägenheter har rasat.",
          "zh": "超过250栋公寓楼已经倒塌。"
        },
        {
          "start": 73.36,
          "end": 78.32,
          "sv": "Många hjälper nu till att leta efter människor under de rasade byggnaderna",
          "zh": "许多人正在帮忙搜寻倒塌建筑废墟下的幸存者"
        },
        {
          "start": 78.48,
          "end": 82.4,
          "sv": "men det är bråttom om man ska hitta fler levande.",
          "zh": "但若要找到更多生还者，时间非常紧迫。"
        },
        {
          "start": 82.56,
          "end": 89.04,
          "sv": "50 000 människor saknas. Det svenska utrikesdepartementet, UD",
          "zh": "5万人下落不明。瑞典外交部（UD）"
        },
        {
          "start": 89.2,
          "end": 95.04,
          "sv": "berättar att det inte finns uppgifter om skadade eller döda svenskar än.",
          "zh": "表示目前尚无关于瑞典公民伤亡的消息。"
        },
        {
          "start": 95.2,
          "end": 101.08,
          "sv": "Presidenten i Venezuela har besökt den hårt drabbade hamnstaden Macuto.",
          "zh": "委内瑞拉总统访问了受灾严重的港口城市马库托。"
        },
        {
          "start": 101.24,
          "end": 105.24,
          "sv": "Hon berättade att det nu kommer hjälp från andra länder.",
          "zh": "她表示其他国家的援助正陆续抵达。"
        },
        {
          "start": 118.8,
          "end": 124.52,
          "sv": "I dag är det den sista dagen för politikerna i Almedalen på Gotland.",
          "zh": "今天是哥特兰岛阿尔梅达伦政治周的最后一天。"
        },
        {
          "start": 124.68,
          "end": 129.72,
          "sv": "Och idag var det Moderaternas ledare Ulf Kristerssons tur att hålla tal.",
          "zh": "今天轮到温和党领袖乌尔夫·克里斯特松发表演讲。"
        },
        {
          "start": 129.88,
          "end": 133.28,
          "sv": "Han lovade bland annat att familjer med små barn",
          "zh": "他承诺，有小孩的家庭等等"
        },
        {
          "start": 133.44,
          "end": 136.6,
          "sv": "ska få behålla mer pengar efter lön.",
          "zh": "税后将能保留更多的钱。"
        },
        {
          "start": 136.76,
          "end": 142.28,
          "sv": "En familj med två barn ska kunna få 5 000 mer i månaden.",
          "zh": "一个有两个孩子的家庭每月可以多得5000克朗。"
        },
        {
          "start": 142.44,
          "end": 148.68,
          "sv": "Just nu är det mycket varmt i Sverige och flera andra länder i Europa.",
          "zh": "目前瑞典和欧洲其他几个国家天气非常炎热。"
        },
        {
          "start": 148.84,
          "end": 151.08,
          "sv": "Det kallas för värmebölja.",
          "zh": "这被称为热浪。"
        },
        {
          "start": 151.24,
          "end": 156.32,
          "sv": "Men sån här värme hade det inte kunnat bli för 50 år sen.",
          "zh": "但这样的高温在50年前是不可能出现的。"
        },
        {
          "start": 156.48,
          "end": 161.48,
          "sv": "Nu är det i snitt 3,5 grader varmare, säger forskare.",
          "zh": "研究人员说，现在平均气温高出了3.5度。"
        },
        {
          "start": 161.64,
          "end": 164.6,
          "sv": "De säger också att det beror på människan.",
          "zh": "他们还说这是人类造成的。"
        },
        {
          "start": 164.76,
          "end": 168.84,
          "sv": "Vi fortsätter att släppa ut gaser som påverkar klimatet.",
          "zh": "我们持续排放影响气候的气体。"
        },
        {
          "start": 169,
          "end": 175.12,
          "sv": "På grund av värmen är det mycket stor risk för bränder i Sverige",
          "zh": "由于高温，瑞典发生火灾的风险非常大"
        },
        {
          "start": 175.28,
          "end": 178.68,
          "sv": "framför allt i Götaland och Svealand.",
          "zh": "尤其是在约塔兰和斯韦阿兰地区。"
        },
        {
          "start": 178.84,
          "end": 183.32,
          "sv": "Därför ska man, enligt myndigheter, vara försiktig om man eldar utomhus",
          "zh": "因此，当局提醒大家，户外生火时要格外小心"
        },
        {
          "start": 183.48,
          "end": 188.48,
          "sv": "eller om man använder maskiner som det kan slå gnistor om.",
          "zh": "或者使用可能产生火花的机器时也要谨慎。"
        },
        {
          "start": 188.64,
          "end": 194.4,
          "sv": "Det svenska landslaget i fotboll är vidare i fotbolls-VM.",
          "zh": "瑞典国家足球队晋级了世界杯赛事。"
        },
        {
          "start": 194.56,
          "end": 199.16,
          "sv": "Inatt spelade de oavgjort mot Japan. Det blev 1-1.",
          "zh": "昨晚他们与日本打成平局，比分1比1。"
        },
        {
          "start": 199.32,
          "end": 203.96,
          "sv": "Och här ser vi Anthony Elanga göra målet för Sverige.",
          "zh": "这里我们看到安东尼·伊兰加为瑞典打入进球。"
        },
        {
          "start": 204.12,
          "end": 210.4,
          "sv": "I nästa match får Sverige troligtvis möta Norge eller Frankrike.",
          "zh": "下一场比赛瑞典可能将面对挪威或法国。"
        },
        {
          "start": 210.56,
          "end": 214,
          "sv": "Och det var många i Sverige som hejade inatt.",
          "zh": "昨晚瑞典有很多人在为球队加油喝彩。"
        },
        {
          "start": 214.16,
          "end": 218.12,
          "sv": "Så här såg det ut på några platser när Sverige gjorde mål.",
          "zh": "这是瑞典进球时各地的现场情景。"
        },
        {
          "start": 234.52,
          "end": 238.6,
          "sv": "Och det blir alltså mycket varmt i söder i helgen.",
          "zh": "周末南部将会非常炎热。"
        },
        {
          "start": 238.76,
          "end": 242.84,
          "sv": "Imorgon kan det bli över 35 grader varmt på vissa ställen.",
          "zh": "明天某些地方气温可能超过35度。"
        },
        {
          "start": 243,
          "end": 246.64,
          "sv": "I norr blir det sol och moln, men inte så varmt.",
          "zh": "北部将会晴转多云，但不会那么热。"
        },
        {
          "start": 246.8,
          "end": 250,
          "sv": "På söndag fortsätter det att vara varmt i söder",
          "zh": "周日南部将继续保持高温"
        },
        {
          "start": 250.16,
          "end": 255.24,
          "sv": "men det kan komma regn och åska. I norr blir det en del regn.",
          "zh": "但可能会有降雨和雷暴。北部将有些降雨。"
        },
        {
          "start": 255.4,
          "end": 260,
          "sv": "Vi är tillbaka igen efter helgen. Tack och hej!",
          "zh": "我们周末后再见。谢谢，再见！"
        }
      ],
