      "source": "SVT Nyheter på lätt svenska",
      "cefr": "A2–B1",
      "duration": 272,
      "svtPlayUrl": "https://www.svtplay.se/video/jBwwBEM/nyheter-pa-latt-svenska",
      "sourceUrl": "",
      "sourceLinkLabel": "",
